Drupal.behaviors.mainMenu={attach(e){let t=e.getElementById(`toggle-expand`),n=e.getElementById(`main-nav`);if(n){let e=n.getElementsByClassName(`expand-sub`);t.addEventListener(`click`,e=>{t.classList.toggle(`toggle-expand--open`),n.classList.toggle(`main-nav--open`),e.preventDefault()}),Array.from(e).forEach(e=>{e.addEventListener(`click`,e=>{let t=e.currentTarget,n=t.nextElementSibling;t.classList.toggle(`expand-sub--open`),n.classList.toggle(`main-menu--sub-open`)})})}}};